<div class="page-header"><div><p class="eyebrow">COURSE MANAGEMENT</p><h1>Edit course <?= e($course['code']) ?></h1><p>Change programme eligibility and prerequisites before registration history exists. Titles and codes remain editable afterward.</p></div><a href="/courses" class="btn btn-outline-secondary">Back to courses</a></div>
<section class="panel"><form method="post" action="/courses/update" data-validate><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$course['id'] ?>"><div class="form-grid">
<label class="form-label">Course code<input class="form-control" name="code" required maxlength="20" value="<?= e($course['code']) ?>"></label>
<label class="form-label">Title<input class="form-control" name="title" required maxlength="200" value="<?= e($course['title']) ?>"></label>
<label class="form-label">Credit units<input class="form-control" type="number" name="credit_units" min="1" max="99" required value="<?= (int)$course['credit_units'] ?>"></label>
<label class="form-label">Semester<select class="form-select" name="semester_number"><option value="1" <?= (int)$course['semester_number']===1?'selected':'' ?>>First</option><option value="2" <?= (int)$course['semester_number']===2?'selected':'' ?>>Second</option></select></label>
<label class="form-label">Department<select class="form-select" name="department_id" data-department required><?php foreach($departments as $r):?><option value="<?= (int)$r['id'] ?>" <?= (int)$course['department_id']===(int)$r['id']?'selected':'' ?> <?= $r['status']!=='active'?'disabled':'' ?>><?= e($r['name']) ?></option><?php endforeach;?></select></label>
<label class="form-label">Academic level<select class="form-select" name="academic_level_id" required><?php foreach($levels as $r):?><option value="<?= (int)$r['id'] ?>" <?= (int)$course['academic_level_id']===(int)$r['id']?'selected':'' ?> <?= $r['status']!=='active'?'disabled':'' ?>><?= e($r['name']) ?></option><?php endforeach;?></select></label>
<label class="form-label">Programmes (Ctrl/Command-click for multiple)<select class="form-select" name="programme_ids[]" data-programme multiple required size="5"><?php foreach($programmes as $r):?><option value="<?= (int)$r['id'] ?>" data-department-id="<?= (int)$r['department_id'] ?>" <?= in_array((int)$r['id'],$programmeIds,true)?'selected':'' ?> <?= $r['status']!=='active'?'disabled':'' ?>><?= e($r['name']) ?></option><?php endforeach;?></select></label>
<label class="form-label">Prerequisite courses (optional, multiple)<select class="form-select" name="prerequisite_ids[]" multiple size="5"><?php foreach($prerequisites as $r):if((int)$r['id']===(int)$course['id'])continue;?><option value="<?= (int)$r['id'] ?>" <?= in_array((int)$r['id'],$prereqIds,true)?'selected':'' ?>><?= e($r['code'].' · '.$r['title']) ?></option><?php endforeach;?></select></label>
</div><button class="btn btn-primary mt-3" type="submit">Save course changes</button></form></section>
